  vocab=[V("v-dodenherdenking","Dodenherdenking","Dia da Recordação dos Mortos (4 de maio)","noun","de"), V("v-bevrijdingsdag","Bevrijdingsdag","Dia da Libertação (5 de maio)","noun","de"),
         V("v-twee-minuten-stilte","twee minuten stilte","dois minutos de silêncio","expression"), V("v-herdenken","herdenken","homenagear|recordar (os mortos)","verb")],
  ex=[("Op 4 mei is de Dodenherdenking.","A 4 de maio é o Dia da Recordação dos Mortos."),("Om acht uur 's avonds zijn er twee minuten stilte.","Às oito da noite há dois minutos de silêncio."),("Op 5 mei vieren we Bevrijdingsdag.","A 5 de maio celebramos o Dia da Libertação."),("We herdenken de slachtoffers van de oorlog.","Recordamos as vítimas da guerra.")],
