    MA([("multicultureel","multicultural"),("roti","roti"),("rijsttafel","rijsttafel"),("afkomst","origem")], "Diversidade.", ["v-multicultureel","v-roti","v-rijsttafel","v-afkomst"]),
    CO("text","Een mengelmoes van culturen", "In Nederland wonen mensen van heel verschillende afkomst. Door de koloniale geschiedenis zijn er veel Nederlanders met roots in Suriname, Indonesië en de Antillen. Dat zie je ook aan het eten: roti en de Indische rijsttafel zijn heel populair. Later kwamen er ook veel mensen uit Turkije en Marokko, en tegenwoordig uit heel Europa, ook uit Portugal.",
       [("Porque há muitas pessoas com raízes no Suriname e na Indonésia?", ["*Pela história colonial","Pelo turismo","Pelo clima"]),("Que pratos são populares?", ["*Roti e rijsttafel","Pizza e sushi","Bacalhau"]),("De onde vêm muitas pessoas hoje?", ["*De toda a Europa, também de Portugal","Só da Ásia","De lado nenhum"])],
       "História e diversidade (factos gerais).", ["v-multicultureel","v-afkomst","v-roti","v-rijsttafel"]),
    TR("pt-nl","Roterdão é uma cidade multicultural.", ["Rotterdam is een multiculturele stad"], "multiculturele (de-woord).", ["v-multicultureel"]),
    TR("pt-nl","Pessoas de origens diferentes vivem aqui.", ["Mensen van verschillende afkomst wonen hier","Hier wonen mensen van verschillende afkomst"], "afkomst.", ["v-afkomst"]),
    AR("rijsttafel","a rijsttafel","de", "De tafel → de rijsttafel.", ["v-rijsttafel"]),
